<script setup>
import MButton from '../../../components/mds/MButton.vue';
import MEmptyState from '../../../components/mds/MEmptyState.vue';
import MTag from '../../../components/mds/MTag.vue';
defineProps({ dashboard: Object, days: Number, loading: Boolean }); const emit = defineEmits(['range','mentions','sources']);
function formatNsr(value) { return `${Number(value) > 0 ? '+' : ''}${Number(value || 0).toFixed(2)}`; }
</script>
<template><section class="min-h-0 bg-[var(--mds-bg-page)] p-4"><div class="mx-auto max-w-[1200px] space-y-4"><header class="rounded-lg bg-[var(--mds-bg)] px-5 py-4 shadow-[var(--mds-shadow-card)]"><div class="flex items-start justify-between gap-4"><div><h1 class="text-[20px] font-semibold">Giám sát truyền thông</h1><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">Tổng quan dữ liệu đã quét; máy chủ vẫn quyết định quyền và dữ liệu trả về.</p></div><div class="flex flex-wrap justify-end gap-2"><MButton variant="neutral" @click="emit('mentions')">Tin bài</MButton><MButton variant="neutral" @click="emit('sources')">Nguồn tin</MButton><MButton v-for="range in [7,30,90]" :key="range" :variant="days===range?'primary':'neutral'" :loading="loading&&days===range" @click="emit('range',range)">{{ range }} ngày</MButton></div></div></header><MEmptyState v-if="!dashboard" title="Chưa có dữ liệu giám sát" description="Chọn khoảng thời gian hoặc kiểm tra quyền truy cập."/><template v-else><section :class="dashboard.crisis ? 'border-[var(--mds-danger)] bg-[var(--mds-danger-bg)]' : 'border-[var(--mds-success)] bg-[var(--mds-success-bg)]'" class="rounded-lg border px-5 py-4"><div class="flex items-center justify-between gap-4"><div><strong>{{ dashboard.crisis ? 'Cảnh báo khủng hoảng' : 'Thương hiệu đang ổn định' }}</strong><p class="mt-1 text-[13px]">{{ dashboard.crisis ? `${dashboard.neg24} tin tiêu cực trong 24 giờ cần được xử lý.` : 'Chưa có dấu hiệu tiêu cực bất thường trong 24 giờ.' }}</p></div><MTag :color="dashboard.crisis?'danger':'success'">{{ dashboard.crisis?'RỦI RO CAO':'AN TOÀN' }}</MTag></div></section><div class="grid gap-3 sm:grid-cols-2 lg:grid-cols-5"><article v-for="item in [[dashboard.counts.total,'Tổng bài quét'],[dashboard.counts.brand,'Đề cập MISA'],[dashboard.neg24,'Tiêu cực 24h'],[dashboard.counts.industry,'Tin ngành'],[dashboard.counts.competitor,'Đề cập đối thủ']]" :key="item[1]" class="rounded-lg bg-[var(--mds-bg)] p-4 shadow-[var(--mds-shadow-card)]"><strong class="text-[24px] leading-7">{{ item[0] }}</strong><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">{{ item[1] }}</p></article></div><div class="grid gap-4 lg:grid-cols-2"><section class="rounded-lg bg-[var(--mds-bg)] p-5 shadow-[var(--mds-shadow-card)]"><h2 class="text-[15px] font-semibold">Sắc thái đề cập MISA</h2><div class="mt-4 grid grid-cols-3 gap-3 text-center"><div><strong class="text-[20px] text-[var(--mds-success)]">{{ dashboard.sentiment.positive }}</strong><p class="text-[12px]">Tích cực</p></div><div><strong class="text-[20px]">{{ dashboard.sentiment.neutral }}</strong><p class="text-[12px]">Trung tính</p></div><div><strong class="text-[20px] text-[var(--mds-danger)]">{{ dashboard.sentiment.negative }}</strong><p class="text-[12px]">Tiêu cực</p></div></div><p class="mt-4 rounded-md bg-[var(--mds-bg-page)] px-3 py-2 text-[13px]">NSR: <strong>{{ formatNsr(dashboard.nsr) }}</strong></p></section><section class="rounded-lg bg-[var(--mds-bg)] p-5 shadow-[var(--mds-shadow-card)]"><h2 class="text-[15px] font-semibold">Lần quét gần nhất</h2><div v-if="dashboard.lastRun" class="mt-4 space-y-2 text-[13px]"><p>Trạng thái: <strong>{{ dashboard.lastRun.status || '—' }}</strong></p><p>{{ dashboard.lastRun.fetched }} bài · {{ dashboard.lastRun.newMentions }} mới · {{ dashboard.lastRun.analyzed }} đã chấm</p><p class="text-[var(--mds-text-secondary)]">{{ dashboard.lastRun.startedAt || 'Chưa có thời điểm' }}</p></div><p v-else class="mt-4 text-[13px] text-[var(--mds-text-secondary)]">Chưa có lịch sử quét.</p></section></div><section class="rounded-lg bg-[var(--mds-bg)] shadow-[var(--mds-shadow-card)]"><header class="border-b border-[var(--mds-border-light)] px-5 py-4"><h2 class="text-[15px] font-semibold">Cảnh báo gần đây</h2></header><MEmptyState v-if="!dashboard.alerts.length" title="Chưa có cảnh báo" description="Các cảnh báo từ máy chủ sẽ xuất hiện tại đây."/><div v-else class="divide-y divide-[var(--mds-border-light)]"><article v-for="alert in dashboard.alerts" :key="alert.id" class="px-5 py-3"><div class="flex items-start gap-2"><MTag :color="alert.level==='critical'?'danger':alert.level==='warning'?'warning':'info'">{{ alert.level }}</MTag><div><strong class="text-[13px]">{{ alert.title }}</strong><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">{{ alert.detail }}</p></div></div></article></div></section></template></div></section></template>
